            end.length +
            leftOverhead +
            (right ? rightOverhead + rightWidth + rightFill : 0) +
            1;
        const maxLeft = renderedWidth - reserved;
        left = maxLeft > 0 ? safeTruncateToWidth(left, maxLeft, "…") : "";
        leftWidth = safeVisibleWidth(left);
        fill =
            renderedWidth -
            start.length -
            end.length -
            (left ? leftWidth + leftOverhead : 0) -
            (right ? rightOverhead + rightWidth + rightFill : 0);
