        const fill = " ".repeat(Math.max(0, contentWidth - fastContent.visibleWidth));
        return `${boxFrameText(theme, BOX_VERTICAL, frameColor)}${sidePad}${fastContent.text}${fill}${sidePad}${boxFrameText(theme, BOX_VERTICAL, frameColor)}`;
